            "file_exists check should be Satisfied when file is present, got: {:?}",
            status
        );
    }

    #[test]
    fn file_exists_check_missing_when_file_absent() {
        use crate::requirements::registry::{Requirement, RequirementCheck};

        let temp = TempDir::new().unwrap();
