                    RequirementCheck::CommandSucceeds("false".to_string()), // fails
                    RequirementCheck::CommandSucceeds("false".to_string()), // fails
                ])],
                install_template: Some("any-install".to_string()),
                install_hint: None,
                depends_on: vec![],
                install_requires: None,
