        );
    }

    #[test]
    fn custom_requirement_service_reachable_check_type() {
        use crate::config::{CustomRequirement, CustomRequirementCheck};

        let temp = TempDir::new().unwrap();

        let mut custom = std::collections::HashMap::new();
        custom.insert(
