            );
        }

        let stdout = String::from_utf8_lossy(&output.stdout);
        if let Some(sha) = stdout
            .lines()
            .next()
            .and_then(|line| line.split_whitespace().next())
        {
            return Ok(sha.to_string());
        }
    }

    bail!("Could not resolve ref '{refspec}' from {url}")
}

