            .args([
                "clone",
                bare_path.to_string_lossy().as_ref(),
                work_dir.to_string_lossy().as_ref(),
            ])
            .output()
            .unwrap();
        assert!(output.status.success(), "clone failed");

        // Configure git user for commits
        for (key, val) in [("user.name", "Test"), ("user.email", "test@test.com")] {
