                "clone",
                &bare_path.to_string_lossy(),
                &work_dir.to_string_lossy(),
            ])
            .output()
            .unwrap();

        for (key, val) in [("user.name", "Test"), ("user.email", "test@test.com")] {
            std::process::Command::new("git")
                .args(["config", key, val])
